// TestGet sends GET /api/node/{hostname}/memory and checks each answer's
// response.
func (s *APIGetPublicTestSuite) TestGet() {
	s.api.Run(s.T(), []servertest.Case{
		{
			Name: "when the example \"A host with 8 GiB, 2 GiB of it free\" is sent, the host's result is returned",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/memory",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"memory.get",
				memory.GetInput{},
				servertest.Completed("server1", `{"memory":{"total":8589934592,"free":2147483648,"used":4294967296}}`),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"hostname":"server1","memory":{"free":2147483648,"total":8589934592,"used":4294967296},"status":"ok"}]}`,
		},
		{
			Name: "when the example \"A host with 8 GiB, 2 GiB of it free\" is broadcast, every host's result is returned",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/_all/memory",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"_all",
				"memory.get",
				memory.GetInput{},
				servertest.Completed("server1", `{"memory":{"total":8589934592,"free":2147483648,"used":4294967296}}`),
				servertest.Skipped("server2"),
				servertest.Failed("server3", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"hostname":"server1","memory":{"free":2147483648,"total":8589934592,"used":4294967296},"status":"ok"},{"error":"unsupported","hostname":"server2","status":"skipped"},{"error":"boom","hostname":"server3","status":"failed"}]}`,
		},
		{
			Name: "when the host skips it, its row says skipped",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/memory",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"memory.get",
				memory.GetInput{},
				servertest.Skipped("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"unsupported","hostname":"server1","status":"skipped"}]}`,
		},
		{
			Name: "when the host fails it, its row says failed",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/memory",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"memory.get",
				memory.GetInput{},
				servertest.Failed("server1", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"boom","hostname":"server1","status":"failed"}]}`,
		},
		{
			Name: "when the host never answers, its row says timeout",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/memory",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"memory.get",
				memory.GetInput{},
				servertest.TimedOut("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"","hostname":"server1","status":"timeout"}]}`,
		},
		{
			Name: "when the job client fails, it is a 500",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/memory",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"memory.get",
				memory.GetInput{},
			).Fails(servertest.ErrUnreachable),
			WantCode: http.StatusInternalServerError,
		},
		{
			Name: "when broadcast and the job client fails, it is a 500",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/_all/memory",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"_all",
				"memory.get",
				memory.GetInput{},
			).Fails(servertest.ErrUnreachable),
			WantCode: http.StatusInternalServerError,
		},
	})
}

// TestGetValidationHTTP sends requests the API refuses before any job is
// queued.
